{
  "$schema": "https://static.modelcontextprotocol.io/schemas/2025-12-11/server.schema.json",
  "name": "com.aihomedesign/aihomedesign-mcp",
  "title": "AI HomeDesign MCP",
  "description": "MCP server to virtually stage, redesign, enhance and declutter real-estate photos.",
  "version": "1.0.0",
  "websiteUrl": "https://aihomedesign.com/mcp",
  "repository": {
    "url": "https://github.com/AIHomeDesign/aihomedesign-mcp",
    "source": "github"
  },
  "remotes": [
    {
      "type": "streamable-http",
      "url": "https://mcp.aihomedesign.com/{connector_token}/mcp",
      "variables": {
        "connector_token": {
          "description": "Your personal connector token. Generate it at https://aihomedesign.com/mcp by pasting your AI HomeDesign API key — the token is returned in the connector URL and looks like 'aihd_...'. Treat it like a password.",
          "isRequired": true,
          "isSecret": true
        }
      }
    }
  ]
}
